// HTTP-обёртка над единым axios-инстансом из store/api.
// Существует для обратной совместимости со всеми *Service.js — публичный API
// (get/post/put/patch/delete/postFormData/setTokens/clearTokens/refreshAccessToken/downloadFile)
// сохранён 1-в-1 с предыдущей fetch-реализацией.
//
// Refresh-токенов и редирект на /login при провале выполняет axios-интерсептор
// в store/api.js — здесь дублирующая логика удалена (это и был смысл C.7).
import api, { clearAuthData } from '../store/api';
import { API_ENDPOINTS } from '../config/api';

// Опция `includeAuth: false` пробрасывается через служебный заголовок `_skipAuth`,
// который интерсептор axios распознаёт и удаляет до отправки.
const buildConfig = (options = {}) => {
    const { includeAuth = true, headers = {}, ...rest } = options;
    const cfg = { ...rest, headers: { ...headers } };
    if (!includeAuth) cfg.headers._skipAuth = true;
    return cfg;
};

const httpService = {
    async get(url, options = {}) {
        const response = await api.get(url, buildConfig(options));
        return response.data;
    },

    async post(url, data, options = {}) {
        const response = await api.post(url, data, buildConfig(options));
        return response.data;
    },

    async put(url, data, options = {}) {
        const response = await api.put(url, data, buildConfig(options));
        return response.data;
    },

    async patch(url, data, options = {}) {
        const response = await api.patch(url, data, buildConfig(options));
        return response.data;
    },

    async delete(url, options = {}) {
        await api.delete(url, buildConfig(options));
        return true;
    },

    // FormData: переопределяем Content-Type, чтобы axios + браузер сами выставили
    // multipart/form-data с правильным boundary. Иначе подхватился бы дефолт
    // application/json из axios-инстанса.
    async postFormData(url, formData, options = {}) {
        const cfg = buildConfig(options);
        const response = await api.post(url, formData, {
            ...cfg,
            headers: { ...cfg.headers, 'Content-Type': 'multipart/form-data' },
        });
        return response.data;
    },

    // Скачивание файла: используется библиотечно (старый downloadFile),
    // documentService.download() имеет собственную реализацию и сюда не заходит.
    async downloadFile(url, filename) {
        const response = await api.get(url, { responseType: 'blob' });
        const blobUrl = window.URL.createObjectURL(response.data);
        const a = document.createElement('a');
        a.href = blobUrl;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(blobUrl);
    },

    // Сохранение токенов после login/register. Axios читает их из localStorage
    // в request-интерсепторе при каждом запросе, поэтому in-memory кеша не держим.
    setTokens(accessToken, refreshToken) {
        if (accessToken) {
            localStorage.setItem('accessToken', accessToken);
        } else {
            localStorage.removeItem('accessToken');
        }
        if (refreshToken) {
            localStorage.setItem('refreshToken', refreshToken);
        } else {
            localStorage.removeItem('refreshToken');
        }
    },

    clearTokens() {
        clearAuthData();
    },

    // Ручной refresh — оставлен для совместимости с authService.refreshToken().
    // Обычный 401-refresh выполняется в axios response-интерсепторе автоматически.
    async refreshAccessToken() {
        try {
            const refreshToken = localStorage.getItem('refreshToken');
            if (!refreshToken) return false;
            const response = await api.post(
                API_ENDPOINTS.AUTH.REFRESH,
                { refreshToken },
                { headers: { _skipAuth: true } }
            );
            const { accessToken, refreshToken: newRefreshToken } = response.data || {};
            if (accessToken) {
                this.setTokens(accessToken, newRefreshToken || refreshToken);
                return true;
            }
            return false;
        } catch (error) {
            console.error('Failed to refresh token:', error);
            return false;
        }
    },
};

export default httpService;
