import React from 'react';
import {
  Dialog, DialogTitle, DialogContent, DialogContentText,
  DialogActions, Button, CircularProgress
} from '@mui/material';

// Универсальный confirm-диалог с кастомным текстом и цветом подтверждения.
// <ConfirmDialog
//   open={open}
//   title="Удаление склада"
//   message={<>Удалить склад <b>{wh.name}</b>?</>}
//   confirmText="Удалить"
//   confirmColor="error"        // 'error' | 'warning' | 'success' | 'primary' | ...
//   busy={busy}                 // блокирует кнопки + спиннер
//   onClose={...}
//   onConfirm={...}
// />
const ConfirmDialog = ({
  open,
  onClose,
  onConfirm,
  title,
  message,
  confirmText = 'Подтвердить',
  cancelText = 'Отмена',
  confirmColor = 'primary',
  busy = false,
  maxWidth = 'xs',
}) => {
  return (
    <Dialog open={open} onClose={() => !busy && onClose?.()} maxWidth={maxWidth} fullWidth>
      <DialogTitle>{title}</DialogTitle>
      <DialogContent>
        <DialogContentText component="div">{message}</DialogContentText>
      </DialogContent>
      <DialogActions>
        <Button onClick={onClose} disabled={busy} autoFocus>
          {cancelText}
        </Button>
        <Button onClick={onConfirm} variant="contained" color={confirmColor} disabled={busy}>
          {busy ? <CircularProgress size={20} color="inherit" /> : confirmText}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default ConfirmDialog;
