import { useMemo, useEffect, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import useDirectoryFetch from './useDirectoryFetch';
import { selectUser } from '../store/slices/authSlice';
import {
    fetchWarehouses,
    setWarehouses,
    selectWarehousesState,
} from '../store/slices/warehousesSlice';
import {
    fetchSuppliers,
    setSuppliers,
    selectSuppliersState,
} from '../store/slices/suppliersSlice';
import {
    fetchEmployees,
    setEmployees,
    selectEmployeesState,
} from '../store/slices/employeesSlice';
import productService from '../services/productService';

// Универсальный билдер хука над Redux-кешем справочника.
// Возвращает тот же интерфейс, что и useDirectoryFetch — { data, loading, error, refresh, setData },
// чтобы страницы переключились на кеширование без правок.
//
// args: selector (state -> { data, loading, error, loadedForKey }), thunk (orgId -> action),
//       setAction (action creator: setX(list)), keyOf (user -> string|null)
const useDirectorySlice = (selector, thunk, setAction, keyOf) => {
    const dispatch = useDispatch();
    const user = useSelector(selectUser);
    const key = keyOf(user);
    const { data, loading, error, loadedForKey } = useSelector(selector);

    useEffect(() => {
        // !loading защищает от двойного dispatch при одновременном mount двух компонентов:
        // первый запустил fetch → loading=true; второй увидит !== key, но не запустит
        // повторный запрос. После rejected/fulfilled loadedForKey === key — больше не сработает.
        if (key && loadedForKey !== key && !loading) {
            dispatch(thunk(key));
        }
    }, [dispatch, key, loadedForKey, loading, thunk]);

    const refresh = useCallback(() => {
        if (!key) return Promise.resolve(null);
        return dispatch(thunk(key)).unwrap().catch(() => null);
    }, [dispatch, key, thunk]);

    const setData = useCallback(
        (next) => {
            const value = typeof next === 'function' ? next(data) : next;
            dispatch(setAction(value));
        },
        [dispatch, data, setAction]
    );

    // loading=true пока ключ есть, но кеш ещё не наполнен — иначе skeleton не покажется
    // на самом первом монтировании (Redux state.loading false до dispatch).
    const effectiveLoading = loading || (!!key && loadedForKey !== key);

    return { data, loading: effectiveLoading, error, refresh, setData };
};

// Склады текущей организации
export const useWarehouses = () => useDirectorySlice(
    selectWarehousesState,
    fetchWarehouses,
    setWarehouses,
    (user) => user?.organizationId || null,
);

// Сотрудники организации
export const useEmployees = () => useDirectorySlice(
    selectEmployeesState,
    fetchEmployees,
    setEmployees,
    (user) => user?.organizationId || null,
);

// Поставщики (фильтрация по X-Organization-Id на бэке)
export const useSuppliers = () => useDirectorySlice(
    selectSuppliersState,
    fetchSuppliers,
    setSuppliers,
    (user) => user?.organizationId || null,
);

// Inventory по складу — ad-hoc, нет смысла кешировать в Redux (зависит от warehouseId,
// меняется часто после операций). Оставляем на useDirectoryFetch.
export const useInventoryByWarehouse = (warehouseId) => {
    const fetcher = useMemo(
        () => () => warehouseId ? productService.getInventory(warehouseId) : Promise.resolve([]),
        [warehouseId]
    );
    return useDirectoryFetch(fetcher, [warehouseId]);
};

export { useDirectoryFetch };
